#!/usr/bin/env node
/**
 * Generate the native app icons from the same brand artwork the web app uses.
 *
 * The web/PWA icons come from public/icon.svg (via @vite-pwa/assets-generator).
 * The native apps used to ship Capacitor's generic default icon, because there
 * was no source and no generation step — and ios/ and android/ are gitignored,
 * regenerated by `npx cap add` on every build, so a checked-in icon wouldn't
 * survive. This runs @capacitor/assets after `cap sync` to render the icons from
 * assets/ (the same rings/brand as public/icon.svg): a full-bleed icon-only.svg
 * for iOS + the Android legacy icons, and icon-foreground/background.svg for the
 * Android adaptive icon.
 *
 * Explicit --ios/--android flags only (never --pwa): the PWA icons and manifest
 * are owned by vite-pwa, and letting this tool touch them would fight it. A
 * no-op with a clear message when neither native project is present, so it can
 * sit unconditionally in the build script and never fail a build.
 */

import { existsSync } from 'node:fs'
import { execFileSync } from 'node:child_process'

/** The platform flags for whichever native projects exist, given an existence probe. */
export function platformFlags(exists) {
  const flags = []
  if (exists('ios/App')) flags.push('--ios')
  if (exists('android')) flags.push('--android')
  return flags
}

if (process.argv[1] && import.meta.url.endsWith(process.argv[1].split('/').pop())) {
  const flags = platformFlags(existsSync)

  if (flags.length === 0) {
    console.log(
      'generate-native-icons: no ios/ or android/ project found, skipping (run `npx cap add` first).',
    )
    process.exit(0)
  }

  const args = ['capacitor-assets', 'generate', ...flags, '--assetPath', 'assets']
  console.log(`generate-native-icons: npx ${args.join(' ')}`)
  execFileSync('npx', args, { stdio: 'inherit' })
}
